package pe.greenminds.ecomind.community.application.internal.commandservices;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.greenminds.ecomind.community.application.commandservices.EventRegistrationCommandService;import pe.greenminds.ecomind.community.application.outboundservices.CommunityActorGateway;import pe.greenminds.ecomind.community.domain.model.aggregates.EventRegistration;import pe.greenminds.ecomind.community.domain.model.commands.*;import pe.greenminds.ecomind.community.domain.repositories.*;import pe.greenminds.ecomind.shared.application.result.*;
@Service public class EventRegistrationCommandServiceImpl implements EventRegistrationCommandService{private final EventRepository events;private final EventRegistrationRepository registrations;private final CommunityActorGateway actors;public EventRegistrationCommandServiceImpl(EventRepository e,EventRegistrationRepository r,CommunityActorGateway a){events=e;registrations=r;actors=a;}
 @Transactional public Result<EventRegistration,ApplicationError> handle(RegisterForEventCommand c){var event=events.findById(c.eventId());if(event.isEmpty())return Result.failure(ApplicationError.notFound("Event",String.valueOf(c.eventId())));if(registrations.findByEventIdAndUserId(c.eventId(),c.userId()).filter(r->"REGISTERED".equals(r.status())).isPresent())return Result.failure(ApplicationError.conflict("Event registration","The user already has an active registration"));int count;if("INDIVIDUAL".equals(c.registrationType())){if(c.familyId()!=null)return Result.failure(ApplicationError.validationError("Event registration","Individual registration cannot include a family id"));count=1;}else if("FAMILY".equals(c.registrationType())){if(c.familyId()==null)return Result.failure(ApplicationError.validationError("Event registration","Family id is required"));try{count=actors.requireFamilyParentAndCount(c.userId(),c.familyId());}catch(SecurityException e){return Result.failure(ApplicationError.forbidden("FAMILY_REGISTRATION_FORBIDDEN",e.getMessage()));}}else return Result.failure(ApplicationError.validationError("Event registration","Registration type must be INDIVIDUAL or FAMILY"));int occupied=registrations.findByEventId(c.eventId()).stream().filter(r->"REGISTERED".equals(r.status())).mapToInt(EventRegistration::participantCount).sum();if(occupied+count>event.get().getCapacity())return Result.failure(ApplicationError.conflict("Event capacity","Event capacity exceeded"));try{return Result.success(registrations.save(new EventRegistration(null,c.eventId(),c.userId(),c.registrationType(),c.familyId(),count,"REGISTERED")));}catch(Exception e){return Result.failure(ApplicationError.unexpected("Event registration",e.getMessage()));}}
 @Transactional public Result<Void,ApplicationError> handle(CancelEventRegistrationCommand c){var registration=registrations.findById(c.registrationId()).filter(r->r.eventId().equals(c.eventId()));if(registration.isEmpty())return Result.failure(ApplicationError.notFound("Event registration",String.valueOf(c.registrationId())));if(!registration.get().userId().equals(c.requestedBy()))return Result.failure(ApplicationError.forbidden("EVENT_REGISTRATION_CANCEL_FORBIDDEN","Only the registration owner may cancel it"));if("CANCELLED".equals(registration.get().status()))return Result.failure(ApplicationError.businessRuleViolation("EVENT_REGISTRATION_ALREADY_CANCELLED","Registration is already cancelled"));var r=registration.get();registrations.save(new EventRegistration(r.id(),r.eventId(),r.userId(),r.registrationType(),r.familyId(),r.participantCount(),"CANCELLED"));return Result.success(null);}}
